/* Current village catalog. Legacy build/save IDs are deliberately preserved. */
window.VILLAGE_ASSET_CATALOG={
 broken_fence:{file:'palisade',name:'Деревянный частокол',width:5.2,depth:1.3,front:0},
 market_ruin:{file:'market_ruin',name:'Заброшенный торговый ряд',width:7.8,depth:3.1,front:0},
 house_ruin:{file:'house_ruin',name:'Разрушенная изба',width:5.5,depth:6.7,front:0},
 tent_ruin:{file:'tent_ruin',name:'Разрушенная торговая палатка',width:3.8,depth:4.2,front:0},
 gate_ruin:{file:'gate_ruin',name:'Разрушенные ворота',width:5.2,depth:2.43,front:0},
 circle:{file:'circle',name:'Ритуальный круг',width:6.5,depth:6.1,front:0},
 tower:{file:'tower',name:'Смотровая вышка',width:4,depth:3.66,front:0},
 totem:{file:'totem',name:'Деревянный обрядовый тотем',width:1.7,depth:1.7,front:0}
};
window.createVillageAssetPack=(T,api)=>{
 const templates={},maps={},wind={value:0},cache=new WeakMap(),surfaces=[];let environment;
 const catalog=window.VILLAGE_ASSET_CATALOG;
 function surface(material,normal,reflection){if(!material?.isMeshStandardMaterial)return material;if(material.userData.villageSurface)return material;material.userData.villageSurface=true;surfaces.push(material);material.normalMap??=normal;material.normalScale?.set(.55,.55);if(!material.roughnessMap&&reflection){material.roughnessMap=reflection;material.roughness=1;/* shader reverses a low reflectance map into high roughness */const prev=material.onBeforeCompile;material.onBeforeCompile=shader=>{prev.call(material,shader);shader.fragmentShader=shader.fragmentShader.replace('roughnessFactor *= texelRoughness.g;','roughnessFactor *= clamp(1.0-texelRoughness.g,0.72,0.98);')};const old=material.customProgramCacheKey.bind(material);material.customProgramCacheKey=()=>old()+'village-reflectance-v1'}material.metalness=Math.min(material.metalness||0,.08);material.envMapIntensity=.28;material.needsUpdate=true;return material}
 function derive(material){if(!material?.isMeshStandardMaterial||material.userData.villageSurface)return;const image=material.map?.image;if(!image||!image.width||typeof document==='undefined')return;try{let pair=cache.get(image);if(!pair){const c=document.createElement('canvas');c.width=c.height=256;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(image,0,0,256,256);const pixels=x.getImageData(0,0,256,256),height=new Float32Array(65536);for(let i=0;i<height.length;i++)height[i]=(pixels.data[i*4]+pixels.data[i*4+1]*2+pixels.data[i*4+2])/1020;const normal=x.createImageData(256,256),reflect=x.createImageData(256,256);for(let y=0;y<256;y++)for(let col=0;col<256;col++){const i=y*256+col,k=i*4,dx=(height[y*256+Math.min(255,col+1)]-height[y*256+Math.max(0,col-1)])*.35,dy=(height[Math.min(255,y+1)*256+col]-height[Math.max(0,y-1)*256+col])*.35,len=Math.hypot(dx,dy,1);normal.data[k]=128-dx/len*127;normal.data[k+1]=128-dy/len*127;normal.data[k+2]=128+127/len;normal.data[k+3]=255;reflect.data[k]=reflect.data[k+1]=reflect.data[k+2]=20+height[i]*36;reflect.data[k+3]=255}const make=data=>{const canvas=document.createElement('canvas');canvas.width=canvas.height=256;canvas.getContext('2d').putImageData(data,0,0);const t=new T.CanvasTexture(canvas);t.flipY=material.map.flipY;t.wrapS=material.map.wrapS;t.wrapT=material.map.wrapT;t.repeat.copy(material.map.repeat);t.encoding=T.LinearEncoding;return t};pair=[make(normal),make(reflect)];cache.set(image,pair)}surface(material,...pair)}catch(e){console.warn('Surface texture unavailable',e)}}
 function apply(root){root.traverse(o=>{if(o.isMesh)for(const m of(Array.isArray(o.material)?o.material:[o.material])){derive(m);if(root.userData.villageObject?.id==='lantern')sway(m,'lantern',new T.Box3().setFromObject(o).getSize(new T.Vector3()).y)}})}
 function sway(material,id,height){if(!['totem','tent_ruin','market_ruin','lantern'].includes(id)||material.userData.microWind)return;material.userData.microWind=true;const old=material.onBeforeCompile,cacheKey=material.customProgramCacheKey.bind(material);material.onBeforeCompile=shader=>{old.call(material,shader);shader.uniforms.villageMicroWind=wind;shader.vertexShader='uniform float villageMicroWind;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>',`#include <begin_vertex>
 float villageTop=smoothstep(${(height*.62).toFixed(5)},${height.toFixed(5)},position.y);
 transformed.x+=sin(villageMicroWind*.72+position.y*2.)*villageTop*${id==='totem'?'0.003':'0.0015'};
 transformed.z+=sin(villageMicroWind*.47+position.x)*villageTop*0.0015;`)};material.customProgramCacheKey=()=>cacheKey()+'micro-wind-'+id;material.needsUpdate=true}
 async function load(){const loader=new T.GLTFLoader(),tl=new T.TextureLoader(),texture=url=>new Promise((ok,no)=>tl.load(url,t=>{t.flipY=false;t.encoding=T.LinearEncoding;ok(t)},undefined,no));await Promise.all(Object.entries(catalog).map(async([id,c])=>{const path='assets/village/'+c.file;const [g,n,r]=await Promise.all([new Promise((ok,no)=>loader.load(path+'.glb',ok,undefined,no)),texture(path+'-normal.png'),texture(path+'-reflection.png')]);templates[id]=g.scene;maps[id]=[n,r];g.scene.traverse(o=>{if(!o.isMesh)return;o.material=o.material.clone();surface(o.material,n,r);api.material(o.material);const box=new T.Box3().setFromObject(o);sway(o.material,id,box.max.y)})}));return true}
 function create(id,variant=0){const c=catalog[id],template=templates[id],root=new T.Group();if(!template)return root;let visual;if(id==='totem'){const parts=template.children.filter(o=>o.isMesh);visual=parts[Math.abs(variant)%parts.length].clone(true)}else visual=template.clone(true);const box=new T.Box3().setFromObject(visual),size=box.getSize(new T.Vector3()),center=box.getCenter(new T.Vector3()),scale=id==='totem'?2.9/new T.Box3().setFromObject(template).getSize(new T.Vector3()).y:c.width/size.x;visual.position.set(-center.x,-box.min.y,-center.z);const body=new T.Group();body.scale.setScalar(scale);body.rotation.y=c.front;body.add(visual);root.add(body);root.userData.authoredVillage=id;root.userData.frontYaw=c.front;root.traverse(o=>{if(o.isMesh){o.castShadow=o.receiveShadow=true;o.userData.navigationIgnore=true}});const proxyMaterial=new T.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false});const addProxy=(geometry,x,y,z)=>{const p=new T.Mesh(geometry,proxyMaterial);p.position.set(x,y,z);p.userData.outlineIgnore=true;root.add(p)};if(id==='circle'){addProxy(new T.CylinderGeometry(3.12,3.12,.25,20),0,.125,0);addProxy(new T.CylinderGeometry(2.62,2.62,.52,20),0,.26,0);for(let i=0;i<3;i++){const a=i*Math.PI*2/3;addProxy(new T.CylinderGeometry(.17,.22,2.8,6),Math.sin(a)*2.6,1.4,Math.cos(a)*2.6)}}else if(id==='totem'){const h=size.y*scale;addProxy(new T.CylinderGeometry(.26,.33,h,6),0,h/2,0)}else{const h=size.y*scale;addProxy(new T.BoxGeometry(c.width,h,c.depth),0,h/2,0)}return root}
 function initEnvironment(renderer,scene){if(typeof document==='undefined')return;try{const env=new T.Scene();env.background=new T.Color('#7a8b83');const ceiling=new T.Mesh(new T.SphereGeometry(20,24,12),new T.ShaderMaterial({side:T.BackSide,vertexShader:'varying vec3 p;void main(){p=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'varying vec3 p;void main(){float h=normalize(p).y;vec3 c=mix(vec3(.12,.16,.11),vec3(.42,.51,.55),smoothstep(-.2,.8,h));gl_FragColor=vec4(c,1.);}'}));env.add(ceiling);const pmrem=new T.PMREMGenerator(renderer);environment=pmrem.fromScene(env);scene.environment=environment.texture;pmrem.dispose();ceiling.geometry.dispose();ceiling.material.dispose()}catch(e){console.warn('Village reflection environment unavailable',e)}}
 return {load,create,apply,surface,initEnvironment,tick:seconds=>{wind.value=seconds;for(const material of surfaces)material.envMapIntensity=api.state?.()?.ui.sceneTime==='night'?.08:.25},catalog};
};
